package com.yeyamo_mobile.api.graph_service.config;
import java.nio.charset.StandardCharsets;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.core.GrantedAuthority;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.web.SecurityFilterChain;
@Configuration@EnableMethodSecurity public class GraphSecurityConfig{
 @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/actuator/info","/v3/api-docs/**","/swagger-ui/**").permitAll().requestMatchers(HttpMethod.GET,"/api/v1/culture-graph/**").permitAll().requestMatchers("/api/v1/admin/culture-graph/**").hasAnyRole("ADMIN","SUPER_ADMIN").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build();}
 @Bean JwtDecoder decoder(@Value("${jwt.secret}")String s){return NimbusJwtDecoder.withSecretKey(new SecretKeySpec(s.getBytes(StandardCharsets.UTF_8),"HmacSHA256")).build();}
 private JwtAuthenticationConverter converter(){JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(j->{var roles=j.getClaimAsStringList("roles");return roles==null?java.util.List.of():roles.stream().map(r->(GrantedAuthority)new SimpleGrantedAuthority(r.startsWith("ROLE_")?r:"ROLE_"+r)).toList();});return c;}
}
